"use client";
import VideoPlayer from '../../components/VideoPlayer/page.jsx';
import { useState, useEffect } from "react";
import axios from "axios";


function useVideoSource(apiUrl) {
  const [video, setVideo] = useState({ url: null, subtitle: null }); // ✅ já inicia com objeto

  useEffect(() => {
    (async () => {
      try {
        const res = await axios.get(apiUrl);
        console.log(res.data);
        const videoUrl = res.data.sources[0].url ?? null;
        const subtitleUrl = res.data.subtitles[0].url ?? null;

        setVideo({ url: videoUrl, subtitle: subtitleUrl });
      } catch (err) {
        console.error("Erro ao carregar vídeo:", err);
      }
    })();
  }, [apiUrl]);

  return video; // sempre retorna objeto
}

export default function Page() {
  const { url, tracks } = useVideoSource(" https://yumaapi.vercel.app/watch?episodeId=dragon-ball-509$episode$10218&type=sub&server=megacloud");

  if (!url) return <p>Carregando vídeo...</p>;

  return <VideoPlayer src={url} subtitles={tracks} />;
}